-- CreateIndex (CONCURRENTLY)
--
-- Disclaimer:
-- - CREATE INDEX CONCURRENTLY cannot run inside a transaction. This migration must stay a
--   single statement so Prisma Migrate on PostgreSQL can apply it outside a transaction.
-- - Builds are slower and use more I/O than a blocking CREATE INDEX; if the build is
--   interrupted, Postgres may leave an INVALID index that must be dropped and recreated.
-- - Do not edit this file after it has been applied to any database: Prisma checksums
--   migrations; add a new migration instead.
-- - Requires PostgreSQL that supports CONCURRENTLY with IF NOT EXISTS (use a new migration
--   without IF NOT EXISTS if you must support older versions).
--
-- Partial index over only the end users that carry an auth restriction, so the restricted
-- registry reload in proxy/auth/auth_checks.py stops scanning the whole table when no rows
-- match. The WHERE clause must stay textually identical to _RESTRICTED_END_USER_PREDICATE in
-- that module: PostgreSQL only serves a partial index for a query whose predicate it can prove
-- equivalent, and the loader's query is written parameter-free for exactly that reason.
CREATE INDEX CONCURRENTLY IF NOT EXISTS "LiteLLM_EndUserTable_restricted_user_id_idx" ON "LiteLLM_EndUserTable"("user_id") WHERE (
    blocked = TRUE
    OR budget_id IS NOT NULL
    OR allowed_model_region IS NOT NULL
    OR default_model IS NOT NULL
    OR object_permission_id IS NOT NULL
    OR models <> '{}'
);
